function adminLocale(){return ['tr','en','zh','ar'].includes((document.documentElement?.lang||"tr").split('-')[0])?(document.documentElement?.lang||"tr").split('-')[0]:'tr'}
function adminText(value){const lang=adminLocale();if(lang==='tr')return value;const keys=Object.keys(adminTranslations).sort((a,b)=>b.length-a.length);let output='',position=0;while(position<value.length){const key=keys.find(k=>value.startsWith(k,position));if(key){output+=adminTranslations[key][lang];position+=key.length}else{output+=value[position++];}}return output}
function adminHtml(parts,...values){return parts.reduce((html,part,index)=>html+adminText(part)+(index<values.length?values[index]:''),'')}
function adminCopy(key) { const lang = (document.documentElement?.lang||"tr").split('-')[0]; const text = { tr: { empty: "Henüz firma başvurusu yok.", zero: "0 yeni firma başvurusu", hint: "Yeni başvurular e-posta onayından sonra görünür.", refresh: "Yenile", loading: "Başvurular yükleniyor…" }, en: { empty: "No company applications yet.", zero: "0 new company applications", hint: "New applications appear after email confirmation.", refresh: "Refresh", loading: "Loading applications…" }, zh: { empty: "暂无企业申请。", zero: "0个新企业申请", hint: "邮箱验证后显示新申请。", refresh: "刷新", loading: "正在加载申请…" }, ar: { empty: "لا توجد طلبات شركات بعد.", zero: "0 طلبات شركات جديدة", hint: "تظهر الطلبات بعد تأكيد البريد الإلكتروني.", refresh: "تحديث", loading: "جار تحميل الطلبات…" } }; return (text[lang] || text.tr)[key]; }
// In-page dialogs: Escape cancels, focus returns to the initiating control.
(() => {
    let cancelActive;
    function open({ title, text, expected, confirmLabel = adminText("Tamam"), url }) {
        cancelActive?.();
        return new Promise(resolve => {
            const previous = document.activeElement, dialog = document.createElement("dialog");
            dialog.className = "admin-dialog";
            if (url)
                dialog.classList.add("admin-document-dialog");
            const heading = document.createElement("h2");
            heading.id = "admin-dialog-title";
            heading.textContent = title;
            dialog.setAttribute("aria-labelledby", heading.id);
            dialog.append(heading);
            if (text) {
                const p = document.createElement("p");
                p.textContent = text;
                dialog.append(p);
            }
            let input;
            if (expected !== undefined) {
                const label = document.createElement("label");
                label.textContent = adminHtml `Onaylamak için yazın: ${expected}`;
                input = document.createElement("input");
                input.autocomplete = "off";
                label.append(input);
                dialog.append(label);
            }
            if (url) {
                const frame = document.createElement("iframe");
                frame.title = adminText("Firma do\u011Frulama belgesi");
                frame.referrerPolicy = "no-referrer";
                frame.src = url;
                dialog.append(frame);
                const p = document.createElement("p");
                p.textContent = adminText("Belge g\u00F6r\u00FCnm\u00FCyorsa dosyay\u0131 cihaz\u0131n\u0131za indirebilirsiniz.");
                const link = document.createElement("a");
                link.textContent = adminText("Belgeyi indir");
                link.href = url;
                link.download = "";
                p.append(" ", link);
                dialog.append(p);
            }
            const actions = document.createElement("div");
            actions.className = "admin-dialog-actions";
            const back = document.createElement("button");
            back.type = "button";
            back.className = "secondary";
            back.textContent = url ? adminText("Kapat") : adminText("Vazge\u00E7");
            actions.append(back);
            const ok = document.createElement("button");
            ok.type = "button";
            ok.textContent = confirmLabel;
            if (!url) {
                ok.disabled = !!input;
                actions.append(ok);
            }
            dialog.append(actions);
            document.body.append(dialog);
            const finish = value => { dialog.close(); dialog.remove(); if (cancelActive === cancel)
                cancelActive = null; previous?.isConnected && previous.focus(); resolve(value); };
            const cancel = () => finish(null);
            cancelActive = cancel;
            back.addEventListener("click", cancel);
            dialog.addEventListener("cancel", event => { event.preventDefault(); cancel(); });
            dialog.addEventListener("click", event => { if (event.target === dialog) {
                const r = dialog.getBoundingClientRect();
                if (event.clientX < r.left || event.clientX > r.right || event.clientY < r.top || event.clientY > r.bottom)
                    cancel();
            } });
            input?.addEventListener("input", () => { ok.disabled = input.value !== expected; });
            ok.addEventListener("click", () => { if (!ok.disabled)
                finish(input ? input.value : true); });
            dialog.showModal();
            (input || back).focus();
        });
    }
    window.MarbleAdminUI = { open, notify(text) { const root = document.getElementById("mb-admin-root"); root.querySelector("[data-admin-notice]")?.remove(); const p = document.createElement("p"); p.dataset.adminNotice = "true"; p.className = "admin-message"; p.setAttribute("role", "status"); p.textContent = text; root.prepend(p); } };
    window.addEventListener("marble-auth", event => { if (!event.detail?.user)
        cancelActive?.(); });
})();
