                    throw new Error(adminText("Ba\u015Fvuru listesini yenileyin."));
                const name = await window.MarbleAdminUI.open({ title: adminText("Firmay\u0131 sil"), text: adminText("Firma, katalog, \u00F6deme, \u00FCyelik ve ilgili talep/teklif kay\u0131tlar\u0131 silinir. Bu i\u015Flem geri al\u0131namaz. Ba\u011Fl\u0131 hesab\u0131n giri\u015Fi engellenir."), expected: app.company_name, confirmLabel: adminText("Kal\u0131c\u0131 sil") });
